//! Python reference vectors for the two supported joint TLS profiles.

use base64::{Engine, engine::general_purpose::STANDARD};
use concurro_relay_tls13::{
    handshake::{
        Profile, ServerFlight, client_hello_with_random, parse_plaintext_record, server_hello,
        validate_client_hello,
    },
    record::{ApplicationRecords, Epoch},
};
use ring::aead;
use serde_json::Value;

/// Load the frozen fixture generated by the operational Python modules.
fn fixture() -> Value {
    serde_json::from_str(include_str!("../../../native/fixtures/tls13.json")).unwrap()
}

/// Decode one base64 field from the frozen fixture.
fn bytes(value: &Value) -> Vec<u8> {
    STANDARD.decode(value.as_str().unwrap()).unwrap()
}

/// Decode one hex field from the frozen vectors.
fn hex(value: &str) -> Vec<u8> {
    value
        .as_bytes()
        .as_chunks::<2>()
        .0
        .iter()
        .map(|pair| u8::from_str_radix(std::str::from_utf8(pair).unwrap(), 16).unwrap())
        .collect()
}

/// Authenticate both Python flights, including ECDSA and RSA-PSS CertificateVerify.
#[test]
fn full_server_flights_match_python() {
    let fixture = fixture();
    let point = bytes(&fixture["joint_point"]);
    let server_secret: [u8; 32] = bytes(&fixture["server_secret"]).try_into().unwrap();
    let client_secret: [u8; 32] = bytes(&fixture["client_secret"]).try_into().unwrap();
    for (name, profile) in [("codex", Profile::Codex), ("claude_h2", Profile::ClaudeH2)] {
        let case = &fixture[name];
        let client = bytes(&case["client"]);
        let server = bytes(&case["server"]);
        let session = validate_client_hello(profile, &client, "fixture.example", &point).unwrap();
        let random: [u8; 32] = client[6..38].try_into().unwrap();
        assert_eq!(
            client_hello_with_random(profile, "fixture.example", &point, random, session)
                .unwrap()
                .wire,
            client
        );
        assert_eq!(server_hello(&server, &session).unwrap().as_slice(), point);
        let mut flight = ServerFlight::new(
            profile,
            &client,
            &server,
            &point,
            server_secret,
            fixture["ca_pem"].as_str().unwrap().as_bytes(),
            "fixture.example",
        )
        .unwrap();
        let records = case["records"].as_array().unwrap();
        assert!(!flight.feed(&bytes(&records[0])).unwrap());
        assert!(!flight.feed(&bytes(&records[1])).unwrap());
        assert!(flight.feed(&bytes(&records[2])).unwrap());
        assert!(flight.feed(&bytes(&records[2])).is_err());
        let (finished, h3) = flight.client_finished(client_secret).unwrap();
        assert_eq!(finished, bytes(&case["client_finished"]));
        assert_eq!(h3.as_slice(), bytes(&case["h3"]));
    }
}

/// Reject altered ciphertext, transcript, trust roots, identity, and Finished.
#[test]
fn authentication_rejects_altered_server_flights() {
    let fixture = fixture();
    let point = bytes(&fixture["joint_point"]);
    let secret: [u8; 32] = bytes(&fixture["server_secret"]).try_into().unwrap();
    let ca = fixture["ca_pem"].as_str().unwrap();
    for (name, profile) in [("codex", Profile::Codex), ("claude_h2", Profile::ClaudeH2)] {
        let case = &fixture[name];
        let client = bytes(&case["client"]);
        let server = bytes(&case["server"]);
        let records: Vec<_> = case["records"]
            .as_array()
            .unwrap()
            .iter()
            .map(bytes)
            .collect();
        let mut changed_record = records[0].clone();
        *changed_record.last_mut().unwrap() ^= 1;
        let mut flight = ServerFlight::new(
            profile,
            &client,
            &server,
            &point,
            secret,
            ca.as_bytes(),
            "fixture.example",
        )
        .unwrap();
        assert!(flight.feed(&changed_record).is_err());
        let mut flight = ServerFlight::new(
            profile,
            &client,
            &server,
            &point,
            secret,
            ca.as_bytes(),
            "fixture.example",
        )
        .unwrap();
        assert!(
            flight
                .feed(&bytes(&case["bad_alpn_record"]))
                .unwrap_err()
                .to_string()
                .contains(if profile == Profile::ClaudeH2 {
                    "ALPN"
                } else {
                    "EncryptedExtensions"
                })
        );

        let mut changed_client = client.clone();
        changed_client[10] ^= 1;
        let mut flight = ServerFlight::new(
            profile,
            &changed_client,
            &server,
            &point,
            secret,
            ca.as_bytes(),
            "fixture.example",
        )
        .unwrap();
        assert!(!flight.feed(&records[0]).unwrap());
        assert!(!flight.feed(&records[1]).unwrap());
        assert!(
            flight
                .feed(&records[2])
                .unwrap_err()
                .to_string()
                .contains("CertificateVerify")
        );

        let mut flight = ServerFlight::new(
            profile,
            &client,
            &server,
            &point,
            secret,
            fixture["other_ca_pem"].as_str().unwrap().as_bytes(),
            "fixture.example",
        )
        .unwrap();
        assert!(!flight.feed(&records[0]).unwrap());
        assert!(!flight.feed(&records[1]).unwrap());
        assert!(
            flight
                .feed(&records[2])
                .unwrap_err()
                .to_string()
                .contains("server certificate rejected")
        );

        let mut other_client = client.clone();
        let start = other_client
            .windows(15)
            .position(|bytes| bytes == b"fixture.example")
            .unwrap();
        other_client[start..start + 15].copy_from_slice(b"another.example");
        let mut flight = ServerFlight::new(
            profile,
            &other_client,
            &server,
            &point,
            secret,
            ca.as_bytes(),
            "another.example",
        )
        .unwrap();
        assert!(!flight.feed(&records[0]).unwrap());
        assert!(!flight.feed(&records[1]).unwrap());
        assert!(
            flight
                .feed(&records[2])
                .unwrap_err()
                .to_string()
                .contains("server certificate rejected")
        );

        let mut flight = ServerFlight::new(
            profile,
            &client,
            &server,
            &point,
            secret,
            ca.as_bytes(),
            "fixture.example",
        )
        .unwrap();
        let bad: Vec<_> = case["bad_finished_records"]
            .as_array()
            .unwrap()
            .iter()
            .map(bytes)
            .collect();
        assert!(!flight.feed(&bad[0]).unwrap());
        assert!(!flight.feed(&bad[1]).unwrap());
        assert!(
            flight
                .feed(&bad[2])
                .unwrap_err()
                .to_string()
                .contains("server Finished mismatch")
        );
    }
}

/// Bind ClientHello and ServerHello to the exact supported negotiation.
#[test]
fn profile_and_negotiation_rejections() {
    let fixture = fixture();
    let point = bytes(&fixture["joint_point"]);
    let codex = bytes(&fixture["codex"]["client"]);
    let h2 = bytes(&fixture["claude_h2"]["client"]);
    assert!(validate_client_hello(Profile::ClaudeH2, &codex, "fixture.example", &point).is_err());
    assert!(validate_client_hello(Profile::Codex, &h2, "fixture.example", &point).is_err());
    assert!(validate_client_hello(Profile::Codex, &codex, "wrong.example", &point).is_err());
    let mut changed = codex.clone();
    changed[0] = 2;
    assert!(validate_client_hello(Profile::Codex, &changed, "fixture.example", &point).is_err());
    let session = validate_client_hello(Profile::Codex, &codex, "fixture.example", &point).unwrap();
    let mut server = bytes(&fixture["codex"]["server"]);
    let suite = server
        .windows(3)
        .position(|part| part == [0x13, 1, 0])
        .unwrap();
    server[suite] ^= 1;
    assert!(server_hello(&server, &session).is_err());
    let mut server = bytes(&fixture["codex"]["server"]);
    server[6..38].copy_from_slice(&hex(
        "cf21ad74e59a6111be1d8c021e65b891c2a211167abb8c5e079e09e2c8a8339c",
    ));
    assert!(server_hello(&server, &session).is_err());
    assert!(
        client_hello_with_random(Profile::Codex, "fixture.example", &point, [7; 32], [8; 32])
            .is_ok()
    );
    assert!(parse_plaintext_record(&[22, 3, 3, 0, 1, 0]).is_ok());
    assert!(parse_plaintext_record(&[22, 3, 3, 0, 2, 0]).is_err());
}

/// Match Python ciphertext and KeyUpdate boundaries, including inner padding.
#[test]
fn traffic_records_match_python_and_preserve_epochs() {
    let fixture = fixture();
    let reference: Value =
        serde_json::from_str(include_str!("../../../native/fixtures/python-wire.json")).unwrap();
    let secret: [u8; 32] = bytes(&fixture["server_secret"]).try_into().unwrap();
    let mut epoch = Epoch::new(secret).unwrap();
    assert_eq!(
        epoch.encrypt(b"fixture body", 23).unwrap(),
        hex(reference["record"]["wire"].as_str().unwrap())
    );
    assert_eq!(epoch.sequence(), 1);
    assert_eq!(
        epoch.updated().unwrap().secret().as_slice(),
        hex(reference["record"]["next_secret"].as_str().unwrap())
    );
    let mut decrypt = Epoch::new(secret).unwrap();
    let wire = hex(reference["record"]["wire"].as_str().unwrap());
    assert_eq!(
        decrypt.decrypt(&wire).unwrap(),
        (23, b"fixture body".to_vec())
    );
    let mut changed = wire.clone();
    changed[10] ^= 1;
    assert!(Epoch::new(secret).unwrap().decrypt(&changed).is_err());
    assert!(
        Epoch::new(secret)
            .unwrap()
            .decrypt(&wire[..wire.len() - 1])
            .is_err()
    );

    let key = concurro_relay_tls13::record::expand::<16>(&secret, b"key").unwrap();
    let unbound = aead::UnboundKey::new(&aead::AES_128_GCM, &key).unwrap();
    let key = aead::LessSafeKey::new(unbound);
    let iv = concurro_relay_tls13::record::expand::<12>(&secret, b"iv").unwrap();
    let mut padded = b"payload\x17\0\0\0".to_vec();
    let header = [23, 3, 3, 0, padded.len() as u8 + 16];
    key.seal_in_place_append_tag(
        aead::Nonce::assume_unique_for_key(iv),
        aead::Aad::from(header),
        &mut padded,
    )
    .unwrap();
    let mut epoch = Epoch::new(secret).unwrap();
    assert_eq!(
        epoch
            .decrypt(&[header.as_slice(), padded.as_slice()].concat())
            .unwrap(),
        (23, b"payload".to_vec())
    );

    let post = &fixture["post_handshake"];
    let mut records = ApplicationRecords::new(secret, [0; 32]).unwrap();
    let wire: Vec<_> = post["records"]
        .as_array()
        .unwrap()
        .iter()
        .map(bytes)
        .collect();
    assert_eq!(records.receive(&wire[0]).unwrap(), None);
    assert_eq!(records.receive(&wire[1]).unwrap(), None);
    assert_eq!(records.tickets(), 1);
    assert_eq!(records.server_updates(), 1);
    assert_eq!(
        records.receive(&wire[2]).unwrap(),
        Some(b"after update".to_vec())
    );
    assert_eq!(
        Epoch::new(secret)
            .unwrap()
            .updated()
            .unwrap()
            .secret()
            .as_slice(),
        bytes(&post["next_secret"])
    );
    assert!(records.send(b"request").is_ok());
}
